from dataclasses import dataclass

@dataclass
class Result:
    valid: bool
    alert: bool

class Monitor:
    def __init__(self):
        self.previous_alert = False   # 每个Monitor实例自己的状态。

    def step(self, distance_m):
        if distance_m <= 35:
            self.previous_alert = True
        elif distance_m >= 41:
            self.previous_alert = False
        return Result(True, self.previous_alert)

monitor = Monitor()                   # 初始化一次。
for d in [45, 34, 38, 42]:
    result = monitor.step(d)          # 每次更新同一个对象。
    print(d, result.alert)

def parse_speed(raw: str) -> float:
    try:
        speed = float(raw)               # 可能抛ValueError。
    except ValueError as exc:
        raise ValueError(f"车速不是数字：{raw!r}") from exc
    if not 0.0 <= speed <= 250.0:
        raise ValueError("车速超出约定范围")
    return speed

for text in ["72.0", "oops", "300"]:
    try:
        speed = parse_speed(text)
        print("成功", speed)
    except ValueError as exc:
        print("拒绝", exc)

import unittest

def kmh_to_mps(speed_kmh: float) -> float:
    return speed_kmh / 3.6

class TestConversion(unittest.TestCase):
    def test_known_value(self):
        # 期望值来自物理单位换算：72 km/h = 20 m/s。
        self.assertAlmostEqual(kmh_to_mps(72.0), 20.0)

    def test_zero(self):
        self.assertEqual(kmh_to_mps(0.0), 0.0)

if __name__ == "__main__":
    unittest.main()  # 也可运行python -m unittest -v test_module。
